files.manifest.json:
{
  "name": "top_customer_complaints_and_fix_priorities",
  "kind": "workflow",
  "description": "Reads customer_feedback.csv, labels themes, ranks complaint themes with traceable row references and quoted examples, and words a concrete fix-first recommendation.",
  "signature": {
    "in": "{\"type\":\"object\",\"properties\":{\"folder\":{\"type\":\"string\"},\"from_date\":{\"type\":\"string\"},\"to_date\":{\"type\":\"string\"},\"customer_filter\":{\"type\":\"string\"},\"channel_filter\":{\"type\":\"string\"},\"top_n\":{\"type\":\"integer\"},\"question\":{\"type\":\"string\"}},\"required\":[\"folder\",\"question\"]}",
    "out": "output of s4"
  },
  "steps": [
    {
      "id": "s1",
      "uses": "parse_customer_feedback",
      "foreach": null,
      "inputs": [
        {
          "param": "folder",
          "source": "$input.folder"
        },
        {
          "param": "from_date",
          "source": "$input.from_date"
        },
        {
          "param": "to_date",
          "source": "$input.to_date"
        },
        {
          "param": "customer_filter",
          "source": "$input.customer_filter"
        },
        {
          "param": "channel_filter",
          "source": "$input.channel_filter"
        }
      ]
    },
    {
      "id": "s2",
      "uses": "label_feedback_themes",
      "foreach": null,
      "inputs": [
        {
          "param": "records",
          "source": "$steps.s1.records"
        }
      ]
    },
    {
      "id": "s3",
      "uses": "rank_feedback_themes",
      "foreach": null,
      "inputs": [
        {
          "param": "records",
          "source": "$steps.s1.records"
        },
        {
          "param": "labels",
          "source": "$steps.s2.labels"
        },
        {
          "param": "top_n",
          "source": "$input.top_n"
        }
      ]
    },
    {
      "id": "s4",
      "uses": "word_fix_priorities",
      "foreach": null,
      "inputs": [
        {
          "param": "ranking",
          "source": "$steps.s3.ranking"
        },
        {
          "param": "question",
          "source": "$input.question"
        }
      ]
    }
  ],
  "output_step": "s4",
  "permissions": {
    "net": [],
    "llm": true
  },
  "budget": {
    "max_tokens_per_run": 12000
  },
  "lineage": {
    "created_by": "factory",
    "uses": [
      "parse_customer_feedback@v2",
      "label_feedback_themes@v1",
      "rank_feedback_themes@v2",
      "word_fix_priorities@v2"
    ]
  },
  "example_input": "{\"folder\":\"novak_trading\",\"top_n\":5,\"question\":\"What are our top customer complaints and what should we fix first?\"}",
  "purpose": "a bot that reads our customer feedback and lists the top complaints and what we should fix first\n\nFiles: folder novak_trading",
  "version": 2,
  "build_usd": 0.2778,
  "build_seconds": 179,
  "headline": "Top {top_n} complaints in {input.folder}: {ranking.0.category} ({ranking.0.percentage}% of cases). Fix first: {fix_first}",
  "examples": [
    "What are the top 5 customer complaints in our feedback?",
    "Show me the biggest issues customers are reporting and what we should prioritize",
    "Analyze complaints from last month and tell me what needs fixing urgently"
  ],
  "voice": "golem",
  "manual_minutes": 45.0,
  "manual_basis": "Reading through feedback records, categorizing complaints, counting occurrences, calculating percentages, identifying root causes, and prioritizing fixes by impact."
}

